from pathlib import Path
from PIL import Image
import re,json
C=Path('chapters/D64/D64_c.html')
if 'id="d64-s-semio"' in C.read_text():raise SystemExit('already assembled')
S={
'HUG':('https://www.hug.ch/sites/interhug/files/2022-10/strategie_anemie_06.10.2022.pdf','HUG — Anémie, 2022, introduction, tableaux 1–5 et 7, annexes anamnèse/examen'),
'LAB':('https://analysenverzeichnis.luks.ch/analysis/Haematogramm_1_%28HG_1%29.html','LUKS — Hémogramme, références adultes et méthode'),
'RET':('https://analysenverzeichnis.luks.ch/analysis/Retikulozyten','LUKS — Réticulocytes, référence analytique'),
'PERLS':('https://www.ebi.ac.uk/europepmc/webservices/rest/PMC9318570/fullTextXML','Lours et collaborateurs — recommandations du Groupe francophone d’hématologie cellulaire, 2022'),
'NGS':('https://www.ebi.ac.uk/europepmc/webservices/rest/PMC9170004/fullTextXML','Recommandations britanniques et européennes — anémies héréditaires rares, 2022, questions 1 et 2'),
'CDA':('https://www.ebi.ac.uk/europepmc/webservices/rest/PMC6519365/fullTextXML','Roy et Babbs — dysérythropoïèse congénitale de type I, 2019'),
'OXY':('https://pac6.ch/fr/chapitres/06-le-monitorage-en-anesthesie-cardiaque/6-5-catheter-pulmonaire-arteriel-de-swan-ganz/6-5-9-transport-doxygene-et-rapport-do2-vo2','Précis d’anesthésie cardiaque 6 — transport d’oxygène'),
'IRON':('https://haematologica.org/article/view/9512','Camaschella, Nai et Silvestri — métabolisme du fer et hepcidine, 2020'),
'ENZ':('https://iubmb.qmul.ac.uk/enzyme/EC2/3/1/37.html','Nomenclature enzymatique internationale — 5-aminolévulinate synthase, réaction 2.3.1.37')}
def sources(*ids):return '<p class="src">Sources consultées le 15 octobre 2026 : '+' ; '.join(f'<a href="{S[i][0]}" target="_blank" rel="noopener">{S[i][1]}</a>' for i in ids)+'.</p>'
def fig(asset,alt,caption):
 w,h=Image.open(asset).size
 return f'<figure><svg role="img" aria-label="{alt}" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><image href="{asset}" width="{w}" height="{h}"/></svg><figcaption>{caption}</figcaption></figure>'
def sec(mark,title,body,*ids):return f'<section class="ilot" id="d64-semio-{mark}" data-semiology="{mark}"><h3>{title}</h3>{body}{sources(*ids)}</section>'
sem='<div class="sci" id="d64-s-semio" role="tabpanel" aria-labelledby="d64-tab-semio">'
sem+=sec('normal','Pour la leçon : quelle est la sémiologie fondamentale et analytique ?',
'''<p>L’anémie est une diminution de la concentration d’hémoglobine; elle ne désigne pas encore une cause. L’analyse clinique distingue sa tolérance immédiate, le mécanisme de la baisse et l’étiologie. Dans les formes rares de D64, cette démarche évite de commencer par un examen invasif ou un traitement supposé universel.</p><p>Normalement, la production médullaire compense l’élimination quotidienne des hématies. Les réticulocytes circulants renseignent sur la sortie de cellules jeunes. Leur nombre doit être confronté à la profondeur de l’anémie : un résultat situé dans un intervalle de laboratoire peut rester insuffisant face à une baisse importante d’hémoglobine.</p><p>Les normes analytiques et les seuils diagnostiques répondent à des questions différentes. Le laboratoire LUKS donne chez l’adulte une hémoglobine de 118–152 g/L chez la femme et 134–170 g/L chez l’homme, avec un volume globulaire moyen de 82–97 fL. La stratégie HUG 2022 utilise, au niveau de la mer, les seuils diagnostiques de 120 g/L chez la femme non enceinte et 130 g/L chez l’homme. Ces références ne deviennent pas des seuils de transfusion.</p>''','HUG','LAB','RET')
sem+=sec('signs','Symptômes : début, progression et retentissement',
'''<p>La fatigue, la dyspnée d’effort, les vertiges et les palpitations peuvent accompagner l’anémie. Le médecin précise leur apparition, leur progression et la perte d’autonomie. La vitesse de baisse compte : une adaptation chronique peut atténuer les symptômes, tandis qu’une baisse rapide déstabilise une personne ayant peu de réserve cardiovasculaire.</p><p>L’entretien recherche un saignement, des symptômes digestifs, des habitudes alimentaires, une maladie inflammatoire ou rénale et les traitements récents. Il documente aussi les médicaments, les toxiques et les antécédents transfusionnels. Une histoire familiale, un ictère ancien ou une splénectomie chez un apparenté peut orienter vers une maladie héréditaire, sans suffire à la démontrer.</p><p>Une présentation congénitale n’impose pas un diagnostic pendant l’enfance. Les recommandations sur les anémies rares associent le récit, l’examen, l’hémogramme, les réticulocytes et les marqueurs d’hémolyse avant de choisir les tests spécialisés. Une fatigue seule ne permet pas de conclure à une anémie sidéroblastique.</p>''','HUG','NGS','CDA')
sem+=sec('mechanisms','Du mécanisme à la manifestation',
'''<p><b>Science → clinique.</b> Une concentration réduite d’hémoglobine diminue la quantité d’oxygène liée par volume de sang. La saturation décrit une proportion de sites occupés, et non cette quantité. Une saturation conservée ne suffit donc pas à exclure un transport d’oxygène insuffisant. L’augmentation du débit cardiaque et de l’extraction tissulaire constitue une compensation, dont l’efficacité dépend du contexte.</p><p>Une baisse de masse érythrocytaire résulte d’une production insuffisante, d’une destruction ou d’une perte accrue. Une expansion du volume plasmatique peut aussi réduire la concentration mesurée. La stratégie HUG cite grossesse, cirrhose et paraprotéinémie dans sa branche d’hémodilution : la concentration ne mesure pas directement la masse totale.</p><p><b>Science → examen.</b> L’association anémie–réticulocytes insuffisants oriente vers un défaut de production efficace. Une moelle riche n’exclut pas ce défaut : dans une dysérythropoïèse, la maturation peut échouer avant une sortie suffisante de cellules. Le frottis et les examens spécialisés précisent ensuite ce mécanisme.</p><p><b>Science → traitement.</b> Un résultat ne désigne pas automatiquement un traitement. Un fer disponible bas sous inflammation n’équivaut pas nécessairement à un épuisement des stocks; l’interprétation associe ferritine, contexte inflammatoire et bilan causal.</p>''','HUG','OXY','CDA','IRON')
sem+=sec('examination','Examen : observation, méthode et limites',
'''<p>Le médecin évalue d’abord la conscience, la respiration et l’hémodynamique. Il confronte la fréquence cardiaque, la pression artérielle et les symptômes au contexte de saignement ou de maladie cardiovasculaire. Une instabilité change immédiatement le lieu de soins.</p><p>L’examen recherche une pâleur, un ictère, des pétéchies ou hématomes, une splénomégalie et les signes orientant vers une cause. La pâleur suggère une anomalie mais ne mesure pas l’hémoglobine. Un ictère peut orienter vers une hémolyse ou une hépatopathie; une splénomégalie ne démontre pas une dysérythropoïèse congénitale. Les constatations sont donc confrontées aux analyses.</p><p>L’hémogramme renseigne sur la concentration, les indices érythrocytaires et les autres lignées. Le frottis décrit taille, forme, couleur et inclusions. Le laboratoire LUKS mesure les réticulocytes par cytométrie et affiche 33–98 G/L comme référence. Le prélèvement, la méthode et la référence du laboratoire figurent dans l’interprétation, surtout si plusieurs résultats semblent discordants.</p>''','HUG','LAB','RET')
sem+=sec('interpretation','Interprétation : décrire avant d’attribuer une cause',
'''<p>Un volume globulaire moyen décrit une moyenne de tailles. Il oriente les hypothèses sans imposer l’étiologie; les HUG rappellent qu’une association de carences peut produire une anémie normocytaire. Les résultats de fer, le frottis, les réticulocytes et le contexte doivent rester associés.</p><p>La stratégie HUG 2022 distingue la réponse régénérative à partir de 120 G/L et l’arégénération sous 70 G/L. Entre ces deux valeurs, le résultat ne doit pas être forcé dans une dichotomie; la sévérité de l’anémie et son évolution restent déterminantes.</p>'''+fig('assets/img/d64/alpha/codex/diagnostic-original.jpg','Deux parcours publiés pour les anémies héréditaires : tests traditionnels ou génétique précoce conditionnelle','Parcours diagnostiques publiés par Roy et Babbs, 2019, figure 1. Le parcours de droite discute une génétique plus précoce, qui peut éviter certains examens médullaires; il ne supprime ni l’anamnèse ni l’examen. Original non redessiné, © 2019 les auteurs, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>.')+'''<p>Un profil des fractions d’hémoglobine non explicatif n’exclut pas toutes les globinopathies. Les recommandations européennes signalent notamment les difficultés de détection de certains variants des gènes alpha. La moelle et la génétique répondent à des questions différentes; leur ordre dépend du contexte et des capacités du laboratoire.</p>''','HUG','NGS','CDA')
sem+=sec('differentials','Différentiels : quels éléments discriminent ?',
'''<p>Une réponse réticulocytaire élevée conduit à chercher rapidement une perte sanguine ou une hémolyse. Une réponse insuffisante conduit à examiner les carences, l’inflammation, les maladies rénales, les médicaments et une atteinte médullaire. Cette orientation initiale ne prétend pas que les mécanismes soient toujours exclusifs.</p><p>Une microcytose ne prouve pas un manque de fer. Les fractions d’hémoglobine, l’histoire familiale et des tests génétiques adaptés peuvent être nécessaires. Une ferritine non basse ne suffit pas non plus à conclure à une anémie sidéroblastique : l’inflammation modifie sa signification.</p><p>Un sidéroblaste en couronne décrit une morphologie après coloration de Perls. Il ne prouve pas, isolément, une néoplasie clonale. Les causes secondaires et le contexte génétique doivent être examinés. La présence d’une anomalie morphologique et l’attribution de sa cause constituent deux étapes distinctes du raisonnement.</p>''','HUG','NGS','PERLS','IRON')
sem+=sec('urgency','Drapeaux rouges et conduite temporelle',
'''<div class="alert"><p>La stratégie HUG 2022 retient comme critères d’urgence une instabilité hémodynamique, une hémoglobine ≤ 70 g/L ou une hémoglobine de 70–80 g/L chez une personne à risque cardiovasculaire. L’évaluation hospitalière et la stabilisation précèdent alors l’enquête sur une forme rare.</p></div><p>La douleur thoracique, la dyspnée importante, la syncope ou les troubles de conscience sont confrontés sans délai aux paramètres vitaux et à l’existence d’un saignement. La décision ne dépend pas d’une attente de génétique ou d’un pourcentage de sidéroblastes.</p><p>La classification de gravité biologique doit rester distincte de la décision transfusionnelle. Chez un adulte stable, l’initiative suisse smarter medicine recommande une stratégie restrictive et une réévaluation après chaque unité. Ce cadre de stabilité ne se transpose pas mécaniquement à un saignement actif ou à une défaillance aiguë.</p>''','HUG')
sem+=sec('limits','Limites : population, méthode et incertitude',
'''<p>Les seuils diagnostiques HUG cités concernent l’adulte au niveau de la mer et distinguent la femme non enceinte. L’enfant et la grossesse requièrent leurs références et leur contexte propres. Une variation par rapport à la valeur habituelle peut aussi justifier une investigation : HUG 2022 mentionne une baisse supérieure à 10 % avec fatigue ou dyspnée, même si le seuil diagnostique n’est pas franchi.</p><p>Les signes généraux ne discriminent pas seuls les formes rares. Aucune fréquence, sensibilité ou spécificité universelle ne leur est attribuée ici. Une image de moelle ou une micrographie de culture ne représente pas l’ensemble du tissu d’une personne.</p><p>Les recommandations de Perls expliquent aussi l’incertitude de comptage près des seuils. Un pourcentage doit préciser son dénominateur et être confronté aux conditions techniques, à la morphologie et à la version de la classification employée.</p><div class="key"><b>À retenir.</b> La clinique hiérarchise l’urgence, l’hémogramme décrit l’anémie et les examens spécialisés cherchent sa cause. Ni une pâleur, ni une ferritine, ni une image isolée ne ferme cette démarche.</div>''','HUG','PERLS','CDA')
sem+=sec('sources','Correspondance entre assertions et passages lus',
'''<p>La stratégie HUG 2022 fonde les critères adultes, les mécanismes généraux, les symptômes, l’examen et l’urgence : introduction, tableaux 1–5 et 7, algorithme et annexes. Le catalogue LUKS fonde les références analytiques de l’hémogramme et des réticulocytes. Le Précis d’anesthésie cardiaque suisse distingue saturation, contenu et transport d’oxygène; ses données spécialisées ne deviennent pas un seuil universel de tolérance.</p><p>Les recommandations européennes sur les anémies héréditaires rares, questions 1 et 2, expliquent les limites de l’analyse des globines et la place des tests génétiques. Les recommandations francophones de Perls, sections de décompte et définition des sidéroblastes, fondent les limites de l’observation morphologique. Roy et Babbs apportent le parcours illustré et la distinction entre culture et diagnostic individuel.</p><p>Ces passages soutiennent les assertions précises de ce panneau. Ils ne signifient pas que toutes les données historiques du cours ou toutes les indications thérapeutiques rares aient reçu une validation indépendante.</p>''','HUG','LAB','RET','OXY','NGS','PERLS','CDA','IRON')
sem+='</div>'
cyto='<div class="sci" id="d64-s-cyto" role="tabpanel" aria-labelledby="d64-tab-cyto" hidden><section class="ilot" id="d64-cyto"><h3>Cytologie analytique : du granule observé au résultat interprétable</h3>'
cyto+='''<p>Une coloration donne une information différente d’une numération. Le frottis sanguin décrit les hématies circulantes; un frottis médullaire permet d’étudier les précurseurs. La coloration de Perls révèle le fer accessible à sa réaction. Le résultat dépend du prélèvement, de la qualité de la coloration et de l’identification correcte des cellules.</p><p>Les recommandations francophones distinguent les sidéroblastes sans granule visible, avec moins de cinq granules, avec au moins cinq granules non périnucléaires et les sidéroblastes en couronne. Ces derniers possèdent au moins cinq granules en position périnucléaire entourant au moins un tiers du noyau. La distinction porte sur une localisation et un nombre, et non sur la seule présence de bleu.</p>'''+fig('assets/img/d64/alpha/codex/perls-original.jpg','Micrographies Perls : types zéro, un, deux et sidéroblastes en couronne','Micrographies publiées de Lours et collaborateurs, 2022, figure 1. A : type 0; B/C : types 1 et 3; D : type 1; E/F : type 2; G/H : type 3. Les cellules illustrent les définitions; leur sélection ne mesure pas la proportion dans une moelle. Original non redessiné, © 2022 les auteurs, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>.')+'''<p>Le dénominateur est l’ensemble des précurseurs érythroïdes comptés. Le groupe recommande 200 cellules, particulièrement près des seuils de 5 ou 15 %; 100 peuvent être acceptées si la cellularité est faible. À 5 % observés, l’intervalle de confiance à 95 % est de 2–11 % pour 100 cellules et de 2–9 % pour 200 selon le tableau publié. Ces plages décrivent l’incertitude d’échantillonnage, pas une évolution réelle de la maladie.</p><p>Une valeur voisine d’un seuil appelle donc une analyse critique, une vérification technique ou une relecture selon le laboratoire. La version de classification, les causes secondaires et les données génétiques restent nécessaires. La coloration ne permet pas de déduire seule le caractère clonal ou héréditaire.</p><div class="key"><p><b>Science → clinique.</b> La découverte de couronnes oriente une enquête; elle n’explique pas à elle seule les symptômes ou la gravité.</p><p><b>Science → examen.</b> Un pourcentage doit préciser la population comptée et le nombre de cellules.</p><p><b>Science → traitement.</b> Une image ou un seuil morphologique isolé ne justifie pas un traitement étiologique avant l’analyse des causes.</p><p><b>À retenir.</b> L’interprétation associe définition, dénominateur, qualité technique et contexte. Une différence numérique faible peut relever du comptage plutôt que d’une modification biologique.</p></div>'''+sources('PERLS','HUG','NGS')+'</section></div>'
s=C.read_text();s=s.replace('<div class="sci-bar ui" role="tablist">','<div class="sci-bar ui" role="tablist"><button id="d64-tab-semio" role="tab" aria-selected="true" aria-controls="d64-s-semio" data-s="d64-s-semio">Sémiologie fondamentale et analytique</button>',1)
s=s.replace('aria-selected="true" aria-controls="d64-s01-panel"','aria-selected="false" aria-controls="d64-s01-panel"',1)
s=s.replace('</div><div class="chap-body sci-body"><div class="sci" id="d64-s01-panel">','<button id="d64-tab-cyto" role="tab" aria-selected="false" aria-controls="d64-s-cyto" data-s="d64-s-cyto">Cytologie et analyse morphologique</button></div><div class="chap-body sci-body">'+sem+cyto+'<div class="sci" id="d64-s01-panel" hidden>',1)
# Original assets with source-specific captions retained except the removed derived anatomy.
replacements={'assets/img/cycle2/d64/01-diagnostic-cda.png':'assets/img/d64/alpha/codex/diagnostic-original.jpg','assets/img/cycle2/d64/02-perls-normal-couronnes.png':'assets/img/d64/alpha/codex/perls-original.jpg','assets/img/cycle2/d64/04-regulation-oxygene.png':'assets/img/d64/alpha/codex/oxygen-regulation-original.jpg','assets/img/cycle2/d64/06-maturation-cda.jpg':'assets/img/d64/alpha/codex/erythroblast-microscopy-original.jpg'}
for a,b in replacements.items():s=s.replace(a,b)
pattern=r'<figure data-evidence="IMG-D64-S01-1">.*?</figure><p>La zone supérieure.*?</p>'
newfig=fig('assets/img/d64/alpha/codex/erythroblast-microscopy-original.jpg','Microscopie électronique publiée : érythroblaste témoin et cellule de dysérythropoïèse congénitale de type I','Microscopie électronique de culture, Roy et Babbs, 2019, figure 3 : A, érythroblaste témoin au septième jour de culture; B, cellule de type I avec binucléation et zones claires de chromatine indiquées par les flèches. Grossissement annoncé : × 4000. Ces vues de culture ne mesurent pas l’architecture d’une moelle entière. © 2019 les auteurs, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>.')+'<p>La comparaison illustre une différence de chromatine et de division cellulaire. Elle doit rester reliée aux conditions de culture et au contexte de la publication : elle ne démontre pas, chez une autre personne, la cause d’une anémie. Le diagnostic confronte la morphologie aux données cliniques et moléculaires.</p>'
s,n=re.subn(pattern,newfig,s,flags=re.S);assert n==1,n
s=s.replace('La figure publiée distingue les stades proérythroblastique, basophile, polychromatophile et orthochromatique, puis l’énucléation. Le schéma montre une diminution de taille et une condensation nucléaire ; il illustre une séquence, sans constituer une photographie diagnostique.','La maturation passe par les stades proérythroblastique, basophile, polychromatophile et orthochromatique, puis l’énucléation. La micrographie publiée compare ici une cellule témoin et une cellule dysérythropoïétique; elle ne représente pas toute cette séquence.')
reaction='''<figure><svg role="img" aria-label="Réaction ALAS : glycine et succinyl-coenzyme A donnent 5-aminolévulinate, coenzyme A et dioxyde de carbone" width="900" height="360" viewBox="0 0 900 360"><title>Première réaction de biosynthèse de l’hème</title><desc>La réaction de référence 2.3.1.37 produit du dioxyde de carbone et du coenzyme A; l’eau n’est pas le produit indiqué pour cette réaction.</desc><rect x="25" y="20" width="850" height="85" rx="12" fill="white" stroke="black" stroke-width="2"/><text x="450" y="72" text-anchor="middle" font-size="27">Glycine + succinyl-coenzyme A</text><path d="M450 110 V225 M438 210 L450 225 L462 210" fill="none" stroke="black" stroke-width="2"/><text x="450" y="155" text-anchor="middle" font-size="25">5-aminolévulinate synthase</text><text x="450" y="188" text-anchor="middle" font-size="23">Cofacteur : phosphate de pyridoxal</text><rect x="25" y="230" width="850" height="105" rx="12" fill="white" stroke="black" stroke-width="2"/><text x="450" y="274" text-anchor="middle" font-size="26">5-aminolévulinate</text><text x="450" y="309" text-anchor="middle" font-size="26">+ coenzyme A + dioxyde de carbone</text></svg><figcaption>Réaction biochimique non anatomique selon la nomenclature enzymatique internationale, réaction 2.3.1.37, consultée le 15 octobre 2026. Ce schéma remplace la figure qui indiquait à tort une libération d’eau à cette étape. Il décrit la première réaction; les autres étapes sont expliquées dans le texte. <a href="https://iubmb.qmul.ac.uk/enzyme/EC2/3/1/37.html" target="_blank" rel="noopener">Réaction de référence et cofacteur</a>.</figcaption></figure>'''
s,n=re.subn(r'<figure data-evidence="IMG-D64-S03-1">.*?</figure>',reaction,s,flags=re.S);assert n==1
s=s.replace('(IUBMB EC 2.3.1.37 ; Rhea 12922). La mention H₂O de la première réaction dans le schéma reproduit ci-dessus est une erreur de ce schéma ; elle ne décrit pas la réaction ALAS.','(nomenclature enzymatique 2.3.1.37; Rhea 12922). L’eau n’est pas le produit de cette première réaction.')
s=s.replace('Erratum biochimique proposé :','Réaction biochimique de référence :').replace('IUBMB EC 2.3.1.37','5-aminolévulinate synthase, 2.3.1.37')
# Accessible wrappers preserve pixels and dimensions; no anatomical drawing.
head,tail=s.split('<div class="panel" id="pS" hidden>',1)
def wrap(m):
 tag=m.group();asset=re.search(r'src="([^"]+)"',tag)[1];alt=re.search(r'alt="([^"]+)"',tag)[1];w,h=Image.open(asset).size
 return f'<svg role="img" aria-label="{alt}" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><image href="{asset}" width="{w}" height="{h}"/></svg>'
tail=re.sub(r'<img\b[^>]*>',wrap,tail);s=head+'<div class="panel" id="pS" hidden>'+tail
# Explicit correlations preserve existing mechanisms.
links={
'd64-s01':'<div class="key"><b>Science → clinique.</b> Une production médullaire peut rester inefficace malgré une moelle riche. <b>Science → examen.</b> Le prélèvement distingue cellules, fer et architecture. <b>Science → traitement.</b> La morphologie seule ne désigne pas un traitement étiologique.</div>',
'd64-s02':'<div class="key"><b>Science → clinique.</b> Le contenu en oxygène contribue à la tolérance. <b>Science → examen.</b> Saturation et concentration d’hémoglobine se distinguent. <b>Science → traitement.</b> La décision de soutien doit intégrer l’hémodynamique et les besoins.</div>',
'd64-s03':'<div class="key"><b>Science → clinique.</b> Une anomalie de synthèse peut limiter l’érythropoïèse efficace. <b>Science → examen.</b> La coloration et le bilan du fer répondent à des questions différentes. <b>Science → traitement.</b> Le mécanisme et la cause doivent être identifiés avant un traitement spécifique.</div>',
'd64-s04':'<div class="key"><b>Science → clinique.</b> La morphologie oriente le diagnostic sans prouver seule l’hérédité. <b>Science → examen.</b> Le test génétique doit correspondre à la question clinique. <b>Science → traitement.</b> Une conclusion moléculaire doit être interprétée avant les décisions irréversibles.</div>'}
for id,body in links.items():
 needle=f'<button class="pareto-btn ui" data-k="pareto-{id}">';assert s.count(needle)==1;s=s.replace(needle,body+needle,1)
C.write_text(s)
